<?php

namespace App\Http\Controllers\Api;

use App\Http\Controllers\Controller;
use App\Services\Mail\CrmMailService;
use Illuminate\Http\JsonResponse;
use Illuminate\Http\Request;
use Illuminate\Support\Facades\Log;
use Throwable;

class TwoFactorCodeController extends Controller
{
    public function __construct(
        private readonly CrmMailService $crmMailService,
    ) {}

    /**
     * Mail a 2FA verification code generated by the forms/patient portal.
     * See {@see CrmMailService::sendTwoFactorCode()} for what is stored on the person.
     *
     * Protected by X-API-KEY (service-to-service).
     */
    public function __invoke(Request $request): JsonResponse
    {
        $validated = $request->validate([
            'email'            => ['required', 'email'],
            'code'             => ['required', 'digits:6'],
            'keycloak_user_id' => ['nullable', 'string', 'max:255'],
        ]);

        try {
            $this->crmMailService->sendTwoFactorCode($validated['email'], $validated['code'], $validated['keycloak_user_id'] ?? null);
        } catch (Throwable $e) {
            Log::error('2FA code mail failed', [
                'email' => $validated['email'],
                'error' => $e->getMessage(),
            ]);

            return response()->json(['message' => 'Verzenden van de verificatiecode is mislukt.'], 500);
        }

        return response()->json(['message' => 'Verificatiecode verzonden.']);
    }
}
